import os
import importlib.util

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
top_n = target.top_n


def test_basic_descending():
    assert top_n([1, 5, 3], 2) == [5, 3]


def test_n_zero_returns_empty():
    assert top_n([1, 2, 3], 0) == []


def test_n_larger_than_size_descending():
    assert top_n([1, 5, 3], 5) == [5, 3, 1]


def test_duplicates_preserved():
    assert top_n([2, 2, 1], 2) == [2, 2]


def test_negative_values_descending():
    assert top_n([-1, -5, -3], 2) == [-1, -3]


def test_already_sorted_descending_order_kept():
    # Even when input is already descending, output must be descending.
    assert top_n([9, 7, 5, 3], 3) == [9, 7, 5]

